contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint lockTime, uint amount, uint collectAmount) public payable {
        require(amount >= 0);
        require(collectAmount >= 0);

        // setup: initialize and set MinSum
        c.SetMinSum(collectAmount);
        c.Initialized();

        // read before values
        (uint beforeUnlockTime, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBalance = address(c).balance;

        // make the deciding Put call
        (bool putOk, ) = address(c).call{value: amount}(abi.encodeWithSignature("Put(uint256)", lockTime));

        // read after Put
        (uint afterPutUnlockTime, uint afterPutBalance) = c.Acc(address(this));

        // attempt Collect
        (bool collectOk, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // read after Collect
        (uint afterCollectUnlockTime, uint afterCollectBalance) = c.Acc(address(this));
        uint afterContractBalance = address(c).balance;

        // General rule: successful Put increases Holder.balance by exactly the sent amount
        // and updates unlockTime to block.timestamp+lockTime if larger than previous unlockTime.
        // Successful Collect decreases Holder.balance by exactly _am and decreases
        // address(c).balance by exactly _am, provided preconditions held.
        // More simply: after Collect, if Collect succeeded, the accounting identity
        // afterCollectBalance == afterPutBalance - collectAmount must hold,
        // otherwise balance stays at afterPutBalance.
        // Additionally, a Put should always leave the contract's balance increased by amount.
        assert(
            (beforeContractBalance + amount == address(c).balance + collectAmount) ||
            (!collectOk && address(c).balance == beforeContractBalance + amount)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    receive() external payable {}

    function run(uint lockTime, uint amount, uint collectAmount) public payable {
        require(address(this).balance >= amount);

        // Setup: allow the test contract to become the caller and set MinSum.
        c.SetMinSum(collectAmount);
        c.Initialized();

        // Snapshot before any state-changing call.
        (uint beforeUnlockTime, uint beforeBalance) = c.Acc(address(this));
        uint beforeC = address(c).balance;

        // State-changing Put. Top-level statement.
        c.Put{value: amount}(lockTime);

        // Snapshot after Put.
        (uint afterPutUnlockTime, uint afterPutBalance) = c.Acc(address(this));
        uint afterPutC = address(c).balance;

        // Attempt Collect. Top-level statement, with try/catch for revert flag.
        bool collectOk = true;
        try c.Collect(collectAmount) {
            collectOk = true;
        } catch {
            collectOk = false;
        }

        // Snapshot after Collect.
        (uint afterCollectUnlockTime, uint afterCollectBalance) = c.Acc(address(this));
        uint afterCollectC = address(c).balance;

        // Rule: Put must credit the caller and increase the contract balance by `amount`.
        // Collect, when successful, must debit the caller and decrease the contract balance by `collectAmount`.
        // Collect, when unsuccessful, must leave both the caller's balance and the contract balance as they were after Put.
        assert(
            (afterPutBalance == beforeBalance + amount) &&
            (afterPutC == beforeC + amount) &&
            (
                (collectOk && afterCollectBalance + collectAmount == afterPutBalance && afterCollectC + collectAmount == afterPutC) ||
                (!collectOk && afterCollectBalance == afterPutBalance && afterCollectC == afterPutC)
            )
        );
    }
}

